#include "../renderer.c"
#include <assert.h>
int main(int argc,char **argv){assert(argc==2||argc==3);if(argc==3)setenv("MB3DX_BACKGROUND_DIR",argv[2],1);setenv("MB3DX_MAP_DIR",argv[1],1);scene_defaults();scene.map.number=9876;load_object_map();assert(map_pixels&&map_width==8&&map_height==8);scene.program_enabled=1;scene.program=legacy_program();for(int i=0;i<8;i++)scene.program.slots[i].count=0;scene.program.slots[0]=formula_slot_default(116);scene.program.slots[0].count=1;formula_slot_set_value(&scene.program.slots[0],0,9876);assert(load_height_maps()&&height_maps[0].pixels&&height_maps[0].width==8);scene.preserved_header_valid=1;memcpy(scene.preserved_header+816,"9876.png",9);load_back_picture();assert(back_pixels&&back_width==(argc==3?16:8));puts("Configured Maps folder supplies diffuse maps, height maps and background images.");return 0;}
